{
  "type": "object",
  "properties": {
    "score": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "Eine Bewertung auf einer Skala von 1 bis 10."
    },
    "strengths": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Eine Liste der identifizierten Stärken."
    },
    "weaknesses": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Eine Liste der identifizierten Schwächen."
    },
    "improvement_suggestions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Vorschläge zur Verbesserung."
    },
    "framework_fit": {
      "type": "string",
      "description": "1-2 Sätze darüber, ob und warum das Framework zum Use Case passt."
    },
