parameters.jsCode:
// Alle Daten aus dem vorherigen Node holen
const input = items[0].json;

// Liste der Keys, die nicht für Agenten relevant sind
const excludeKeys = ["submittedAt", "formMode"];

let formattedString = Object.entries(input)
  .filter(([key]) => !excludeKeys.includes(key))
  .map(([key, value]) => `${key}: ${value}`)
  .join('\n');

// Format für Chatinput in Agenten
return {
  chatInput: formattedString
};

