{
  "properties": {
    "framework": {
      "type": "string",
      "enum": [
        "n8n",
        "Cognigy",
        "Google ADK",
        "CrewAI",
        "OpenAI SDK",
        "Claude SDK",
        "LangChain",
        "LangGraph",
        "Keine KI nötig"
      ],
      "description": "Name des empfohlenen Frameworks"
    },
    "ease_of_use": {
      "type": "string",
      "enum": ["High", "Medium", "Hard"],
      "description": "Schwierigkeitsgrad der Implementierung"
    },
    "summary": {
      "type": "string",
      "description": "Ein Satz: Warum genau dieses Framework."
    },
    "reasoning": {
      "type": "string",
      "description": "2-4 Sätze ausführliche Begründung mit Fokus auf Anforderung vs. Aufwand."
    },
    "ki_notwendig": {
      "type": "boolean",
      "description": "Gibt an, ob eine KI-Lösung zwingend erforderlich ist."
    },
    "alternative_ohne_ki": {
      "type": ["string", "null"],
      "description": "Kurze Empfehlung falls keine KI nötig ist, ansonsten null."
    }
  },
  "required": [
    "framework",
    "ease_of_use",
    "summary",
    "reasoning",
    "ki_notwendig",
    "alternative_ohne_ki"
  ]
}
